// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around AdhocRequestBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// AdhocRequestEntityI.
func (c *AdhocRequestColumns) Marshal(w io.Writer) (err error) {
	ent := adhocRequestPool.Get().(*cbdml.InEntityFacts)
	defer adhocRequestPool.Put(ent)
	ent.SetActiveSections(AdhocRequestActiveSections)
	ent.Builder().SetActiveFields(AdhocRequestActiveFields())
	err = AdhocRequestBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("adhocrequest: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("adhocrequest: marshal write: %w", err)
	}
	return
}

// --- Read path (ra-based). ---

// adhocRequestReader composes the readaccess helpers this kind needs.
// Constructed per Unmarshal call; released via defer.
type adhocRequestReader struct {
	EntityId        *ra.ReadAccessFactsPlainEntityIdAttributes
	EntityTimestamp *ra.ReadAccessFactsPlainEntityTimestampAttributes
	Symbol          *ra.ReadAccessFactsTaggedSymbol
	StringArray     *ra.ReadAccessFactsTaggedStringArray
	Bool            *ra.ReadAccessFactsTaggedBool
	BlobArray       *ra.ReadAccessFactsTaggedBlobArray
}

func newAdhocRequestReader() *adhocRequestReader {
	return &adhocRequestReader{
		EntityId:        ra.NewReadAccessFactsPlainEntityIdAttributes(),
		EntityTimestamp: ra.NewReadAccessFactsPlainEntityTimestampAttributes(),
		Symbol:          ra.NewReadAccessFactsTaggedSymbol(),
		StringArray:     ra.NewReadAccessFactsTaggedStringArray(),
		Bool:            ra.NewReadAccessFactsTaggedBool(),
		BlobArray:       ra.NewReadAccessFactsTaggedBlobArray(),
	}
}

func (r *adhocRequestReader) loadFromRecord(rec arrow.Record) (err error) {
	err = r.EntityId.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocrequest: load EntityId: %w", err)
		return
	}
	err = r.EntityTimestamp.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocrequest: load EntityTimestamp: %w", err)
		return
	}
	err = r.Symbol.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocrequest: load Symbol: %w", err)
		return
	}
	err = r.StringArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocrequest: load StringArray: %w", err)
		return
	}
	err = r.Bool.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocrequest: load Bool: %w", err)
		return
	}
	err = r.BlobArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocrequest: load BlobArray: %w", err)
		return
	}
	return
}

func (r *adhocRequestReader) release() {
	if r == nil {
		return
	}
	if r.EntityId != nil {
		r.EntityId.Release()
	}
	if r.EntityTimestamp != nil {
		r.EntityTimestamp.Release()
	}
	if r.Symbol != nil {
		r.Symbol.Release()
	}
	if r.StringArray != nil {
		r.StringArray.Release()
	}
	if r.Bool != nil {
		r.Bool.Release()
	}
	if r.BlobArray != nil {
		r.BlobArray.Release()
	}
}

// Unmarshal appends one row to c per entity in rec, projecting
// the boxer.facts columns through factsschema/ra. Thin wrapper
// around AdhocRequestFillFromArrow — the per-row decode lives there.
func (c *AdhocRequestColumns) Unmarshal(rec arrow.Record) (err error) {
	r := newAdhocRequestReader()
	defer r.release()
	err = r.loadFromRecord(rec)
	if err != nil {
		return
	}
	n := r.EntityId.Len()
	err = AdhocRequestFillFromArrow(
		c,
		n,
		r.EntityId.ValueId,
		r.EntityId.ValueNaturalKey,
		r.EntityTimestamp.ValueTs,
		r.Symbol.Attributes, r.Symbol.Memberships,
		r.StringArray.Attributes, r.StringArray.Memberships,
		r.Bool.Attributes, r.Bool.Memberships,
		r.BlobArray.Attributes, r.BlobArray.Memberships,
	)
	return
}

// --- buscodec.CodecI bridge. ---

// AdhocRequestCodec is the buscodec.CodecI bridge for AdhocRequest. Encodes one row
// through dml_cbor; decodes via cborarrow.Convert + ra-Unmarshal +
// Row(0). Auto-registered in init() so callers using buscodec.Encode
// / Decode route through here instead of the CBOR fallback.
type AdhocRequestCodec struct{}

var _ buscodec.CodecI = (*AdhocRequestCodec)(nil)

// adhocRequestBusCodec is the package-local singleton wired into buscodec.
var adhocRequestBusCodec = &AdhocRequestCodec{}

func (inst *AdhocRequestCodec) Name() (n string) {
	n = "adhocRequest-sparse-cbor"
	return
}

func (inst *AdhocRequestCodec) ContentType() (ct string) {
	ct = "application/x-runtime-facts+rb;kind=adhocRequest"
	return
}

func (inst *AdhocRequestCodec) Encode(v any) (b []byte, err error) {
	var row AdhocRequest
	switch x := v.(type) {
	case AdhocRequest:
		row = x
	case *AdhocRequest:
		if x == nil {
			err = eh.Errorf("adhocrequest: Encode nil *AdhocRequest")
			return
		}
		row = *x
	default:
		err = eh.Errorf("adhocrequest: Encode requires AdhocRequest or *AdhocRequest, got %T", v)
		return
	}
	cols := &AdhocRequestColumns{}
	cols.Append(row)
	var buf bytes.Buffer
	err = cols.Marshal(&buf)
	if err != nil {
		err = eh.Errorf("adhocrequest: Encode marshal: %w", err)
		return
	}
	b = buf.Bytes()
	return
}

func (inst *AdhocRequestCodec) Decode(b []byte, v any) (err error) {
	target, ok := v.(*AdhocRequest)
	if !ok {
		err = eh.Errorf("adhocrequest: Decode requires *AdhocRequest, got %T", v)
		return
	}
	var arrowBuf bytes.Buffer
	err = cborarrow.Convert(bytes.NewReader(b), &arrowBuf)
	if err != nil {
		err = eh.Errorf("adhocrequest: Decode cborarrow: %w", err)
		return
	}
	rd, err := ipc.NewReader(&arrowBuf)
	if err != nil {
		err = eh.Errorf("adhocrequest: Decode ipc reader: %w", err)
		return
	}
	defer rd.Release()
	if !rd.Next() {
		err = eh.Errorf("adhocrequest: Decode expected one Arrow record, got none")
		return
	}
	rec := rd.RecordBatch()
	defer rec.Release()
	cols := &AdhocRequestColumns{}
	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("adhocrequest: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("adhocrequest: Decode expected 1 row")
		return
	}
	*target = cols.Row(0)
	return
}
